fn solve(word: Vec<char>) -> Vec<char> {
    // Helper function to tell if a character belongs to Set A.
    fn is_in_set_a(c: char) -> bool {
        matches!(
            c,
            'A' | 'E' | 'F' | 'H' | 'I' | 'K' | 'L' | 'M' | 'N' | 'T' | 'V' | 'W' | 'X' | 'Y' | 'Z'
        )
    }

    // Check if all characters are in Set A, or all are in Set B.
    if word.iter().all(|&c| is_in_set_a(c)) || word.iter().all(|&c| !is_in_set_a(c)) {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}

